import{_ as i,l as o,o as a,c as s,v as r,p as n,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"数学验证器与等价","description":"","frontmatter":{"title":"数学验证器与等价","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/math-verifier-equivalence.md","filePath":"llm/math-verifier-equivalence.md","lastUpdated":1789023840000}'),h={name:"llm/math-verifier-equivalence.md"};function m(E,e,f,_,u,A){const l=o("Mermaid");return a(),s("div",null,[e[1]||(e[1]=r('<h1 id="数学验证器与等价" tabindex="-1">数学验证器与等价 <a class="header-anchor" href="#数学验证器与等价" aria-label="Permalink to &quot;数学验证器与等价&quot;">​</a></h1><div class="epigraph"><p>$1/2$ 与 $0.5$ 是同一个数；字符串不等价不是答错。校验器的规范比模型更常成为噪声源。</p><footer>—— GSM8K / MATH 的答案核对传统；DeepSeekMath 与 R1 把抽取 + 等价接到 GRPO</footer></div><p><a href="/llm/code-verifier-unittests">上一课</a>把代码 \\(R\\) 写成单测执行。数学没有「跑程序」这么干净：最终答案是表达式、整数或选择题。缺口是：<strong>抽取之后必须定义等价，而不是 <code>strip()</code> 后的字符串相等。</strong> Hendrycks 的 MATH、Cobbe 的 GSM8K、DeepSeekMath 的规则奖励，都在这条规范上。本课写验证器，不重写 <a href="/llm/grpo">GRPO</a> 公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/verifiable-reward">可验证奖励</a> 要求 \\(\\mathrm{check}(\\mathrm{extract}(y), y^\\star)\\)。extract 锁 boxed / 最后一行；check 若是字符串相等，则 \\(\\tfrac12\\)、<code>0.5</code>、<code>1/2</code> 会假阴性，策略被教去模仿金标的书写而不是数学。假阳性同样存在：抽到中间计算当最终答案。规范要版本化，像代码一样 diff。</p><p>符号计算（SymPy 化简后比较）、数值采样（随机点求值）、整数化（DAPO-Math 把题改写成整数答案）是三条路。整数化降低解析失败，也改变题意。复现必须声明用哪条。</p><h3 id="过程胡写、答案碰对" tabindex="-1">过程胡写、答案碰对 <a class="header-anchor" href="#过程胡写、答案碰对" aria-label="Permalink to &quot;过程胡写、答案碰对&quot;">​</a></h3><p>结果验证不管中间步骤。蒙对、抄错再改回、用错误引理得到对的数字，都得 \\(R=1\\)。这是与 <a href="/llm/process-supervision">PRM</a> 的分工：本课只钉终点；逐步合法留给过程模型。R1-Zero 接受终点监督，换来不标步骤。</p><p><span class="marginnote">格式奖励（是否包在 <code>\\boxed{}</code>）应尽早饱和后关掉，否则模型靠格式刷分。可验证课已经警告过这一点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流水线：采样 \\(G\\) 条长链 → 按训练/评测同一套正则抽取 → 规范化（去空格、统一分数线）→ 等价判定 → \\(R\\in\\{0,1\\}\\) 或部分分。等价：对有理数用精确比较；对表达式试解析再 <code>simplify(a-b)==0</code>；失败则回退字符串。超时与解析异常记为 0，并打日志，否则静默假阴会污染优势。</p>',11)),(a(),n(c,null,{default:t(()=>[p(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E9%95%BF%E9%93%BE%20y%22%5D%20--%3E%20EX%5B%22%E6%8A%BD%E5%8F%96%E6%9C%80%E7%BB%88%E7%AD%94%E6%A1%88%22%5D%0A%20%20EX%20--%3E%20N%5B%22%E8%A7%84%E8%8C%83%E5%8C%96%22%5D%0A%20%20N%20--%3E%20EQ%5B%22%E7%AC%A6%E5%8F%B7%20%2F%20%E6%95%B0%E5%80%BC%20%2F%20%E6%95%B4%E6%95%B0%E7%AD%89%E4%BB%B7%22%5D%0A%20%20EQ%20--%3E%20R%5B%22R%20%3D%200%2F1%22%5D%0A%20%20STAR%5B%22%E9%87%91%E6%A0%87%20y*%22%5D%20--%3E%20EQ%0A%20%20R%20--%3E%20GRPO%5B%22%E7%BB%84%E5%86%85%E6%A0%87%E5%87%86%E5%8C%96%E4%BC%98%E5%8A%BF%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>接到 <a href="/llm/ppo-llm">PPO</a> 或 GRPO 时不要把解析失败与数学错误混成同一损失桶。评测脚本必须与训练 \\(R\\) 同源；MATH 官方解析与自写脚本不一致时，分数不可比。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>等价放宽了书写，梯度才对准数学内容。过宽的数值比较（容差太大）会把近似错当对。过严的符号失败会把正确但解析器吃不了的式子当错，策略学会只输出解析器偏好的规范形——又一种黑客。整数化是工程折中：解析稳，表达力下降。</p><p>组内全错时没有相对信号，难题上学习停滞，这是验证器加上群体基线的合取，不是验证器单独的错。温度与题库难度要一起调。</p><p><span class="marginnote">不要把「LLM 检查两式是否相等」当作本课验证器。那是裁判，会把等价噪声换成模型噪声。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>证明题、开放推导没有短答案，本课 \\(R\\) 不够，应走 PRM 或形式化助手（Lean）。代码题走上一课。多目标（对且短、对且可读）留给下一课加权。验证器吞吐高，是推理 RL 的主场；不要为了「统一接口」把数学改回 RM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>数学 \\(R\\) 是抽取 + 等价，不是字符串相等。</li><li>符号、数值、整数化三条规范必须声明；假阴假阳来自规范。</li><li>终点正确不蕴含过程合法；过程走 PRM。</li><li>训练与评测必须同源脚本。</li><li>出处：Cobbe 等 GSM8K；Hendrycks 等 MATH；Shao 等 DeepSeekMath；DeepSeek-AI R1。</li></ul>',9))])}const R=i(h,[["render",m]]);export{P as __pageData,R as default};
